solution.code:
def grade(n):
    """Kembalikan "A" (>= 85), "B" (>= 70), "C" (>= 55), atau "D"."""
    if n >= 85:
        return "A"
    elif n >= 70:
        return "B"
    elif n >= 55:
        return "C"
    return "D"


def rata_rata(nilai):
    """Rata-rata semua nilai di dict, dibulatkan 1 desimal. Dict kosong -> 0.0."""
    if not nilai:
        return 0.0
    return round(sum(nilai.values()) / len(nilai), 1)


def rekap(nilai):
    """List baris f"{nama:<8} {n:>5.1f}  {grade(n)}" sesuai urutan dict."""
    return [f"{nama:<8} {n:>5.1f}  {grade(n)}" for nama, n in nilai.items()]


def parse_baris(baris):
    """ "Ani,88" -> ("Ani", 88.0). Baris tidak valid -> raise ValueError."""
    bagian = baris.split(",")
    if len(bagian) != 2:
        raise ValueError(f"format salah: {baris!r}")
    nama = bagian[0].strip()
    nilai = float(bagian[1])
    if not nama:
        raise ValueError("nama kosong")
    if not 0 <= nilai <= 100:
        raise ValueError("nilai harus 0 sampai 100")
    return nama, nilai


def muat(daftar_baris):
    """Dict nama -> nilai dari baris yang valid, baris rusak dilewati."""
    data = {}
    for baris in daftar_baris:
        try:
            nama, nilai = parse_baris(baris)
        except ValueError:
            continue
        data[nama] = nilai
    return data


class Kelas:
    def __init__(self):
        self.nilai = {}

    def tambah(self, nama, nilai):
        if not 0 <= nilai <= 100:
            raise ValueError("nilai harus 0 sampai 100")
        self.nilai[nama] = float(nilai)

    def terbaik(self):
        if not self.nilai:
            return None
        return max(self.nilai, key=self.nilai.get)

