solution.code:
class Rekening:
    def __init__(self, pemilik, saldo_awal=0):
        self.pemilik = pemilik
        self._saldo = saldo_awal

    def setor(self, jumlah):
        if jumlah > 0:
            self._saldo += jumlah
        return self._saldo

    def tarik(self, jumlah):
        if jumlah > self._saldo:
            return False
        self._saldo -= jumlah
        return True

    def cek_saldo(self):
        return self._saldo

