solution.code:
def baca_nilai(f):
    hasil = {}
    for baris in f:
        baris = baris.strip()
        if not baris:
            continue
        try:
            nama, nilai = baris.split(",")
            hasil[nama.strip()] = float(nilai)
        except ValueError:
            continue
    return hasil

